import{_ as i}from"./chunks/Audio.COine8Wh.js";import{_ as o}from"./chunks/Tags.BJ536pW3.js";import{c as n,o as s,j as a,G as t,ae as r,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const b=JSON.parse('{"title":"Foundation of the Federal Bar Association Charter Amendments Act of 2025","description":"","frontmatter":{"legisId":"2025-12-12-foundation-of-the-federal-bar-association-charter-amendments-act-of-2025","title":"Foundation of the Federal Bar Association Charter Amendments Act of 2025","displayTitle":"Foundation of the Federal Bar Association Charter Amendments Act of 2025","lawNumber":"119-57","billNumber":"S. 616","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ57.xml","publishDate":"2025-12-12T00:00:00-05:00","industries":["government-operations"],"agencies":[],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Foundation of the Federal Bar Association Charter Amendments Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-foundation-of-the-federal-bar-association-charter-amendments-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Foundation of the Federal Bar Association Charter Amendments Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-foundation-of-the-federal-bar-association-charter-amendments-act-of-2025\\",\\"datePublished\\":\\"2025-12-12T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-foundation-of-the-federal-bar-association-charter-amendments-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-12-12-foundation-of-the-federal-bar-association-charter-amendments-act-of-2025.md","filePath":"congress-bills/2025-12-12-foundation-of-the-federal-bar-association-charter-amendments-act-of-2025.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2025-12-12-foundation-of-the-federal-bar-association-charter-amendments-act-of-2025.md"},u=Object.assign(d,{setup(c){return(f,e)=>(s(),n("div",null,[e[0]||(e[0]=a("h1",{id:"foundation-of-the-federal-bar-association-charter-amendments-act-of-2025",tabindex:"-1"},[l("Foundation of the Federal Bar Association Charter Amendments Act of 2025 "),a("a",{class:"header-anchor",href:"#foundation-of-the-federal-bar-association-charter-amendments-act-of-2025","aria-label":'Permalink to "Foundation of the Federal Bar Association Charter Amendments Act of 2025"'},"​")],-1)),t(i),t(o,{list:"/congress-bills"}),e[1]||(e[1]=r('<p>Signed into law on Friday, December 12, 2025. Public Law 119-57, S. 616.</p><p><strong>Headline:</strong> The law modernizes the Foundation of the Federal Bar Association’s charter and gives its bylaws greater control over internal operations.</p><p><strong>Why it matters:</strong> The changes give the foundation more flexibility over membership, leadership, and office location while preserving restrictions on politics, private benefit, and financial risk.</p><p><strong>What the law does:</strong></p><ul><li>Lets the foundation’s bylaws govern membership eligibility and member rights.</li><li>Places governance with the board and lets bylaws set officer duties and election rules.</li><li>Allows the board to locate the principal office anywhere in the United States.</li><li>Permits reasonable compensation, expense reimbursement, employee pay, and grants to Federal Bar Association chapters.</li><li>Bars stock issuance, dividends, political activity, lobbying, insider benefits, and loans to directors, officers, members, or employees.</li><li>Protects members and private individuals from personal liability for foundation obligations.</li><li>Requires dissolution assets to be distributed as the board directs under the charter and bylaws.</li></ul><p><strong>Who it affects:</strong></p><ul><li>The Foundation of the Federal Bar Association and its board, officers, members, and employees.</li><li>Federal Bar Association chapters eligible for foundation grants.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>The law mainly changes the foundation’s internal governance rather than creating new individual rights or duties.</li><li>People working with the foundation receive clearer safeguards against personal liability and improper financial practices.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="foundation-of-the-federal-bar-association-charter-amendments-act-of-2025-1" tabindex="-1">Foundation of the Federal Bar Association Charter Amendments Act of 2025 <a class="header-anchor" href="#foundation-of-the-federal-bar-association-charter-amendments-act-of-2025-1" aria-label="Permalink to &quot;Foundation of the Federal Bar Association Charter Amendments Act of 2025&quot;">​</a></h3><p>This law updates the federal charter of the Foundation of the Federal Bar Association. It gives the foundation’s bylaws greater control over membership, governance, officers, and office location, while retaining limits on political activity, private financial benefit, loans, and claims of federal approval. It also revises rules for legal service and distribution of assets when the foundation dissolves.</p><p><strong>Key takeaways:</strong></p><ul><li>Membership eligibility and members’ rights and privileges are governed by the foundation’s bylaws.</li><li>The board of directors governs the foundation, and the bylaws set the board’s responsibilities and rules for officers and their elections.</li><li>The foundation may not issue stock, pay dividends, engage in political activity, or attempt to influence legislation.</li><li>The foundation may not distribute income or assets for the private benefit of directors, officers, or members, but it may pay approved reasonable compensation, reimburse expenses, award grants to Federal Bar Association chapters, and compensate employees.</li><li>The foundation may not make loans to its directors, officers, members, or employees, and members and private individuals are not personally liable for its obligations.</li><li>The board may choose the foundation’s principal office location in the United States, and remaining assets after dissolution must be distributed as directed by the board in compliance with the charter and bylaws.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ57.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ57.xml</a></p>',15))]))}});export{b as __pageData,u as default};
